function resolveCurrentCopyType(record, expected) {
  if (!record || record.id !== expected.recordId) throw Error('Current inbox record unavailable for CC/BCC selection');
  const value = name => record.getCellValue(name);
  const scalar = x => String(x?.name ?? x ?? '').trim();
  if (scalar(value('Workspace ID (Bison)')) !== expected.workspaceId || scalar(value('reply_message_id')) !== expected.replyId) {
    throw Error('Inbox identity changed; refresh the conversation before sending');
  }
  const links = (value('Clients Table') || []).map(x => typeof x === 'string' ? x : x.id);
  if (links.length !== 1 || links[0] !== expected.workspaceRecordId) throw Error('Inbox client differs from CC/BCC settings');
  const event = scalar(value('Dulcy Reply Agent Event ID'));
  const intent = scalar(value('Dulcy Reply Agent Intent'));
  const currentEvent = `bison:${expected.workspaceRecordId}:${expected.replyId}`;
  // A stale classification from a previous incoming message must not choose recipients.
  return event === currentEvent && intent ? intent : scalar(value('Lead Status'));
}

// Shared EmailBison reply sender v4.
// CC/BCC are resolved from the current workspace and exact incoming message.
// Conversation history is written only by the canonical event pipeline.
const inputData = input.config();
const replyId = String(inputData.replyId || '');
const message = String(inputData.customReply || '');
const senderEmailId = String(inputData.sender_email_id || '');
const workspaceID = String(inputData.workspaceID || '');
const leadId = String(inputData.lead_id || '');
const campaignId = String(inputData.campaign_id || '');
const airtableRecordId = String(inputData.airtable_record || '');
const apiKey = String((Array.isArray(inputData.api) ? inputData.api.find(Boolean) : inputData.api) || '');
const API_ROOT = 'https://send.dulcy.io/api';

function address(value) {
  if (value && typeof value === 'object') return address(value.address || value.email_address || value.email || '');
  const text = String(value || '').trim().toLowerCase();
  const angle = text.match(/<([^<>]+)>/);
  return (angle ? angle[1] : text).trim();
}

function validEmail(value) {
  return /^[^\s<>@]+@[^\s<>@]+\.[^\s<>@]+$/.test(value);
}

function addressList(value) {
  const values = Array.isArray(value) ? value : [value];
  const result = [];
  for (const item of values.flat(Infinity)) {
    if (item && typeof item === 'object') {
      const email = address(item);
      if (email) result.push({ name: String(item.name || '').trim(), email_address: email });
      continue;
    }
    for (const part of String(item || '').split(/[;,\n]+/)) {
      const email = address(part);
      if (email) result.push({ name: '', email_address: email });
    }
  }
  return result;
}

async function requestJson(url, options = {}) {
  const response = await fetch(url, {
    ...options,
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
  });
  const raw = await response.text();
  let payload = {};
  if (raw) {
    try { payload = JSON.parse(raw); }
    catch { throw new Error(`EmailBison returned non-JSON HTTP ${response.status}`); }
  }
  if (!response.ok || payload?.error || payload?.success === false) {
    throw new Error(`EmailBison request failed with HTTP ${response.status}`);
  }
  return payload;
}

function rowsFrom(payload) {
  if (Array.isArray(payload?.data)) return payload.data;
  if (Array.isArray(payload?.data?.data)) return payload.data.data;
  if (Array.isArray(payload?.records)) return payload.records;
  return [];
}

async function authoritativeAccounts() {
  const accounts = [];
  for (let page = 1; page <= 100; page += 1) {
    const payload = await requestJson(`${API_ROOT}/sender-emails?per_page=100&page=${page}`);
    accounts.push(...rowsFrom(payload));
    const meta = payload?.meta || payload?.data?.meta || {};
    const current = Number(meta.current_page || page);
    const last = Number(meta.last_page || current);
    const next = payload?.next_page_url || payload?.links?.next || meta.next_page_url;
    if (!next && current >= last) return accounts;
    if (!next && !Number.isFinite(last)) throw new Error('Sender account pagination is ambiguous');
  }
  throw new Error('Sender account pagination exceeded the safety limit');
}

function explicitTime(raw) {
  if (typeof raw !== 'string' || !/(?:Z|[+-]\d{2}:?\d{2}|\b(?:UT|UTC|GMT))\s*(?:\([^)]*\))?$/i.test(raw.trim())) return null;
  const millis = Date.parse(raw);
  return Number.isFinite(millis) ? new Date(millis).toISOString() : null;
}

function confirmedSend(payload) {
  const reply = payload?.data?.reply || payload?.data || {};
  const id = String(reply.id || reply.uuid || '');
  const status = String(reply.folder || reply.status || '').toLowerCase();
  const sentAt = explicitTime(reply.sent_at)
    || explicitTime(reply.date_sent)
    || (String(reply.type || '').toLowerCase() === 'outgoing email' ? explicitTime(reply.date_received) : null);
  if (!id || !['sent', 'delivered'].includes(status) || !sentAt || Date.parse(sentAt) > Date.now() + 60000) {
    throw new Error('Submission is unconfirmed or queued. Do not clear the draft, advance sent status, or retry automatically; reconcile using the provider response.');
  }
  return { id, sentAt };
}

function copyReplyType(value) {
  const key = String(value?.name || value || '').trim().toLowerCase().replace(/[_-]+/g, ' ').replace(/\s+/g, ' ');
  const aliases = {
    'positive reply': 'interested', positive: 'interested',
    'meeting requested': 'meeting request', 'meeting booked': 'meeting request',
    ooo: 'out of office', 'information request': 'info request',
    referral: 'referred', 'follow up later': 'check back later',
  };
  return aliases[key] || key;
}

function includeWorkspaceCopy(config, kind, type) {
  const scope = config[`${kind}Scope`] || 'all';
  if (scope === 'all') return true;
  if (scope !== 'selected') throw new Error(`Invalid ${kind.toUpperCase()} reply-type setting`);
  const types = config[`${kind}Types`];
  if (!Array.isArray(types) || !types.length || types.some((entry) => typeof entry !== 'string' || !entry.trim())) {
    throw new Error(`Choose at least one ${kind.toUpperCase()} reply type`);
  }
  return types.map(copyReplyType).includes(copyReplyType(type));
}

async function workspaceCopyRecipients() {
  if (!/^\d+$/.test(workspaceID)) throw new Error('Missing EmailBison workspace identity');
  const workspaceQuery = await base.getTable('Workspace IDs').selectRecordsAsync({ fields: ['ID'] });
  const workspaces = workspaceQuery.records.filter((record) => String(record.getCellValue('ID')).trim() === workspaceID);
  if (workspaces.length !== 1) throw new Error('Unique workspace required for CC/BCC settings');
  const settingsQuery = await base.getTable('tbl5nmzPUcNEBSWxH').selectRecordsAsync({ fields: ['Workspace Record ID', 'CC BCC Settings JSON'] });
  const settings = settingsQuery.records.filter((record) => record.getCellValue('Workspace Record ID') === workspaces[0].id);
  if (settings.length > 1) throw new Error('Multiple workspace reply settings; reconcile before sending');
  const raw = settings[0]?.getCellValue('CC BCC Settings JSON');
  let config = {};
  if (raw) {
    try { config = JSON.parse(raw); }
    catch { throw new Error('Invalid workspace CC/BCC settings JSON'); }
    if (!config || Array.isArray(config) || typeof config !== 'object') throw new Error('Invalid workspace CC/BCC settings');
  }
  const currentInbox = await base.getTable('Emails').selectRecordAsync(airtableRecordId);
  const type = resolveCurrentCopyType(currentInbox, {recordId:airtableRecordId, workspaceId:workspaceID, replyId, workspaceRecordId:workspaces[0].id});
  const cc = config.ccEnabled === true && includeWorkspaceCopy(config, 'cc', type) ? addressList(config.cc) : [];
  const bcc = config.bccEnabled === true && includeWorkspaceCopy(config, 'bcc', type) ? addressList(config.bcc) : [];
  if (config.ccEnabled === true && includeWorkspaceCopy(config, 'cc', type) && !cc.length) throw new Error('Auto CC is enabled without recipients');
  if (config.bccEnabled === true && includeWorkspaceCopy(config, 'bcc', type) && !bcc.length) throw new Error('Auto BCC is enabled without recipients');
  return { cc, bcc };
}

if (!replyId || !senderEmailId || !workspaceID || !apiKey || !airtableRecordId || !message.trim()) {
  throw new Error('Missing workspace, thread, sender, API, Airtable record, or reply body');
}

const senderPayload = await requestJson(`${API_ROOT}/sender-emails/${encodeURIComponent(senderEmailId)}`);
const sender = senderPayload?.data;
const senderAddress = address(sender);
if (!sender || String(sender.id) !== senderEmailId || !validEmail(senderAddress)) {
  throw new Error('Authoritative sender account unavailable or mismatched');
}
const senderWorkspace = String(sender.workspace_id || sender.team_id || sender.workspace?.id || '');
if (senderWorkspace && senderWorkspace !== workspaceID) throw new Error('Authoritative sender belongs to a different workspace');

const threadPayload = await requestJson(`${API_ROOT}/replies/${encodeURIComponent(replyId)}/conversation-thread`);
const current = threadPayload?.data?.current_reply;
if (!current || String(current.id) !== replyId) throw new Error('Authoritative conversation does not match the requested reply');
if (leadId && current.lead_id && String(current.lead_id) !== leadId) throw new Error('Authoritative conversation lead mismatch');
if (campaignId && current.campaign_id && String(current.campaign_id) !== campaignId) throw new Error('Authoritative conversation campaign mismatch');
if (current.sender_email_id && String(current.sender_email_id) !== senderEmailId) throw new Error('Authoritative conversation sender mismatch');

const authoritativeLead = address(current.from_email_address);
const requestedLead = address(inputData.leadEmail);
if (!validEmail(authoritativeLead) || authoritativeLead !== requestedLead) {
  throw new Error('To must be the one authoritative external reply author');
}
const originalInbox = address(current.primary_to_email_address);
if (originalInbox && originalInbox !== senderAddress) throw new Error('Original thread recipient differs from the authoritative sender');

const accounts = await authoritativeAccounts();
const internal = new Set(accounts.map(address).filter(validEmail));
internal.add(senderAddress);
if (internal.has(authoritativeLead)) throw new Error('External recipient is the sender or a known sender alias');

const workspaceCopies = await workspaceCopyRecipients();
const seen = new Set([authoritativeLead]);
const cc = [];
for (const entry of [...addressList(inputData.ccEmails ?? inputData.cc), ...workspaceCopies.cc]) {
  if (!validEmail(entry.email_address)) throw new Error('Invalid CC address');
  if (internal.has(entry.email_address)) throw new Error('CC contains the sender or a known sender alias');
  if (!seen.has(entry.email_address)) {
    seen.add(entry.email_address);
    cc.push(entry);
  }
}
const bcc = [];
for (const entry of workspaceCopies.bcc) {
  if (!validEmail(entry.email_address)) throw new Error('Invalid BCC address');
  if (internal.has(entry.email_address)) throw new Error('BCC contains the sender or a known sender alias');
  if (!seen.has(entry.email_address)) {
    seen.add(entry.email_address);
    bcc.push(entry);
  }
}

const result = await requestJson(`${API_ROOT}/replies/${encodeURIComponent(replyId)}/reply`, {
  method: 'POST',
  body: JSON.stringify({
    inject_previous_email_body: true,
    message,
    sender_email_id: Number(senderEmailId),
    content_type: 'html',
    to_emails: [{ name: String(inputData.leadName || current.from_name || ''), email_address: authoritativeLead }],
    cc_emails: cc,
    bcc_emails: bcc,
    reply_all: false,
  }),
});

const confirmation = confirmedSend(result);
// EmailBison's confirmed MANUAL_EMAIL_SENT event is admitted to canonical history.
// Preserve the existing output contract without writing a history snapshot.
const unchangedHistory = String(inputData['Conversation History'] || '');
output.set('sendConfirmed', true);
output.set('providerMessageId', confirmation.id);
output.set('sentAt', confirmation.sentAt);
output.set('convoHistory', unchangedHistory);

