  if (typeof raw !== 'string' || !/(?:Z|[+-]\d{2}:?\d{2}|\b(?:UT|UTC|GMT))\s*(?:\([^)]*\))?$/i.test(raw.trim())) return null;
  const millis = Date.parse(raw);
  return Number.isFinite(millis) ? new Date(millis).toISOString() : null;
}

function sentTime(message) {
  return explicitTime(message?.sent_at)
    || explicitTime(message?.date_sent)
    || explicitTime(message?.event_time)
    || explicitTime(message?.time)
    || explicitTime(message?.timestamp);
}

async function requestJson(url, options = {}) {
  const response = await fetch(url, {
    ...options,
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
  });
  const raw = await response.text();
  let payload = {};
  if (raw) {
    try { payload = JSON.parse(raw); }
    catch { throw new Error(`Smartlead returned non-JSON HTTP ${response.status}`); }
  }
  if (!response.ok || payload?.error || payload?.success === false || payload?.ok === false) {
    throw new Error(`Smartlead request failed with HTTP ${response.status}`);
  }
  return payload;
}

async function history() {
  const payload = await requestJson(`${API_ROOT}/campaigns/${encodeURIComponent(campaignId)}/leads/${encodeURIComponent(leadId)}/message-history?api_key=REDACTED`);
  if (!Array.isArray(payload?.history)) throw new Error('Smartlead message history is unavailable');
  return payload.history;
}

if (!apiKey || !campaignId || !leadId || !emailStatsId || !replyMessageId || !body.trim()) {
  throw new Error('Missing Smartlead campaign, lead, thread, message, or reply body');
}

const before = await history();
const parent = before.find((message) => messageId(message) === replyMessageId)
  || before.filter((message) => String(message?.type || '').toUpperCase() === 'REPLY').at(-1);
if (!parent || (messageId(parent) && messageId(parent) !== replyMessageId)) {
  throw new Error('Authoritative Smartlead parent message does not match the requested reply');
}
const prospect = messageFrom(parent);
const sender = messageTo(parent);
if (!validEmail(prospect) || !validEmail(sender) || prospect === sender) {
  throw new Error('Smartlead external prospect and sending inbox must be distinct verified emails');
}

const knownSenders = new Set(before
  .filter((message) => String(message?.type || '').toUpperCase() === 'SENT')
  .map(messageFrom)
  .filter(validEmail));
knownSenders.add(sender);
const cc = [];
const seen = new Set([prospect]);
for (const email of addressList(cfg.cc)) {
  if (!validEmail(email)) throw new Error('Invalid Smartlead CC address');
  if (knownSenders.has(email)) throw new Error('Smartlead CC contains the sender or a known sender alias');
  if (!seen.has(email)) {
    seen.add(email);
    cc.push(email);
  }
}

const requestBody = {
  email_stats_id: emailStatsId,
  email_body: body.replace(/\r\n?/g, '\n').replace(/\n/g, '<br/>'),
  reply_message_id: replyMessageId,
};
if (cc.length) requestBody.cc = cc;

const accepted = await requestJson(`${API_ROOT}/campaigns/${encodeURIComponent(campaignId)}/reply-email-thread?api_key=REDACTED`, {
  method: 'POST',
  body: JSON.stringify(requestBody),
});
if (accepted?.success !== true) throw new Error('Smartlead did not explicitly accept the reply');

let providerMessageId = String(accepted?.data?.message_id || accepted?.message_id || '').trim();
let confirmedAt = null;
if (providerMessageId) {
  const status = await requestJson(`${API_ROOT}/master-inbox/reply-status?api_key=REDACTED&message_id=${encodeURIComponent(providerMessageId)}`);
  if (status?.ok === true && String(status?.data?.status || '').toUpperCase() === 'COMPLETED') {
    confirmedAt = explicitTime(status?.data?.event_time);
  }
} else {
  const known = new Set(before.map(messageId).filter(Boolean));
  const after = await history();
  const candidates = after.filter((message) => {
    const id = messageId(message);
    return id && !known.has(id)
      && String(message?.type || '').toUpperCase() === 'SENT'
      && messageFrom(message) === sender
      && messageTo(message) === prospect;
  });
  if (candidates.length === 1) {
    providerMessageId = messageId(candidates[0]);
    confirmedAt = sentTime(candidates[0]);
  }
}

if (!providerMessageId || !confirmedAt || Date.parse(confirmedAt) > Date.now() + 60000) {
  throw new Error('Smartlead accepted the reply but has not confirmed a unique completed message. Do not clear the draft, advance sent status, or retry automatically.');
}

output.set('sendConfirmed', true);
output.set('providerMessageId', providerMessageId);
output.set('sentAt', confirmedAt);
